{"content": "1|// The multiplayer message language: one entry per message type, declaring its
2|// direction ('cs' client → server, 'sc' server → client), its wire fields and
3|// its design rate. One shared encode/decode pair is driven by those entries,
4|// so every packet is validated against the same definitions that produce the
5|// protocol table in NOTES.md (`node tools/protocol-table.mjs`).
6|//
7|// Wire format: JSON text frames tagged with `type` — messages are tiny and the
8|// intranet is fast, so readable beats compact. All times are milliseconds in
9|// the shared server clock (clients learn their offset via ping/pong, because
10|// the browser's WebSocket API hides the protocol-level ping/pong from JS).
11|
12|export const STAGES = ['lobby', 'countdown', 'racing', 'finished', 'ceremony'];
13|export const MAX_PLAYERS = 4;
14|
15|const err = (where, why) => new Error(`protocol: ${where} ${why}`);
16|
17|// --- Field validators (used by encode AND decode, so both sides agree) ---
18|
19|function str(v, w) {
20|  if (typeof v !== 'string' || v.length < 1 || v.length > 24) throw err(w, 'must be a 1..24 char string');
21|  return v;
22|}
23|function num(v, w) {
24|  if (typeof v !== 'number' || !Number.isFinite(v)) throw err(w, 'must be a finite number');
25|  return v;
26|}
27|function idNum(v, w) {
28|  if (!Number.isInteger(v) || v < 1) throw err(w, 'must be a positive integer');
29|  return v;
30|}
31|function seedNum(v, w) {
32|  if (!Number.isInteger(v) || v < 0) throw err(w, 'must be a non-negative integer');
33|  return v;
34|}
35|function stageOf(v, w) {
36|  if (!STAGES.includes(v)) throw err(w, `must be one of ${STAGES.join('|')}`);
37|  return v;
38|}
39|function rosterOf(v, w) {
40|  if (!Array.isArray(v) || v.length > MAX_PLAYERS) throw err(w, `must be an array of at most ${MAX_PLAYERS} players`);
41|  return v.map((p, i) => {
42|    if (typeof p !== 'object' || p === null || Array.isArray(p)) throw err(`${w}[${i}]`, 'must be an object');
43|    for (const k of Object.keys(p)) if (k !== 'id' && k !== 'name') throw err(`${w}[${i}]`, `has unknown field ${k}`);
44|    if (!('id' in p) || !('name' in p)) throw err(`${w}[${i}]`, 'needs id and name');
45|    return { id: idNum(p.id, `${w}[${i}].id`), name: str(p.name, `${w}[${i}].name`) };
46|  });
47|}
48|
49|const tOrNull = (v, w) => (v === null ? null : num(v, w));
50|const boolOf = (v, w) => {
51|  if (typeof v !== 'boolean') throw err(w, 'must be a boolean');
52|  return v;
53|};
54|// One results-table row for the settled race: finished players first in
55|// official order (time, then earliest report), DNFs last with t = null.
56|const resultsOf = (v, w) => {
57|  if (!Array.isArray(v) || v.length > MAX_PLAYERS) throw err(w, `must be an array of at most ${MAX_PLAYERS} players`);
58|  return v.map((r, i) => {
59|    if (typeof r !== 'object' || r === null || Array.isArray(r)) throw err(`${w}[${i}]`, 'must be an object');
60|    for (const k of Object.keys(r)) if (k !== 'id' && k !== 'name' && k !== 't' && k !== 'dnf') throw err(`${w}[${i}]`, `has unknown field ${k}`);
61|    if (!('id' in r) || !('name' in r) || !('t' in r) || !('dnf' in r)) throw err(`${w}[${i}]`, 'needs id, name, t and dnf');
62|    return {
63|      id: idNum(r.id, `${w}[${i}].id`),
64|      name: str(r.name, `${w}[${i}].name`),
65|      t: tOrNull(r.t, `${w}[${i}].t`),
66|      dnf: boolOf(r.dnf, `${w}[${i}].dnf`),
67|    };
68|  });
69|};
70|
71|// --- The registry ---
72|
73|export const MESSAGES = {
74|  // client → server
75|  join:       { dir: 'cs', rate: 'once, on entering the lobby', fields: { name: str } },
76|  name:       { dir: 'cs', rate: 'on change, in lobby',          fields: { name: str } },
77|  start:      { dir: 'cs', rate: 'user-triggered',               fields: {} },
78|  pos:        { dir: 'cs', rate: '15 Hz while racing',           fields: { x: num, z: num, h: num, s: num } },
79|  finish:     { dir: 'cs', rate: 'once per race',                fields: { t: num } },
80|  ping:       { dir: 'cs', rate: 'about 1 Hz while syncing',     fields: { t: num } },
81|  // server → client
82|  roster:     { dir: 'sc', rate: 'on change',                    fields: { players: rosterOf, seed: seedNum } },
83|  countdown:  { dir: 'sc', rate: 'once per race',                fields: { goAt: num } },
84|  go:         { dir: 'sc', rate: 'once per race',                fields: { goAt: num } },
85|  posRelay:   { dir: 'sc', rate: 'per player, 15 Hz',            fields: { id: idNum, x: num, z: num, h: num, s: num } },
86|  stage:      { dir: 'sc', rate: 'on change',                    fields: { stage: stageOf } },
87|  disconnect: { dir: 'sc', rate: 'on player leaving',            fields: { id: idNum } },
88|  pong:       { dir: 'sc', rate: 'on ping',                      fields: { t: num, s: num } },
89|  finishInfo: { dir: 'sc', rate: 'per finisher, once',           fields: { id: idNum, t: num } },
90|  results:    { dir: 'sc', rate: 'once, when the race is settled', fields: { players: resultsOf } },
91|};
92|
93|// --- The encode/decode pair ---
94|
95|// encode(type, data) → JSON string, fields validated on the way out.
96|export function encode(type, data) {
97|  const def = MESSAGES[type];
98|  if (!def) throw err(type, 'is not a known message type');
99|  const out = { type };
100|  for (const [f, check] of Object.entries(def.fields)) out[f] = check(data?.[f], `${type}.${f}`);
101|  return JSON.stringify(out);
102|}
103|
104|// decode(text) → { type, data }, or throws on anything unknown or malformed:
105|// bad JSON, non-objects, unknown types, missing/unknown fields, wrong value types.
106|export function decode(text) {
107|  let m = null;
108|  try { m = JSON.parse(text); } catch { /* handled below */ }
109|  if (typeof m !== 'object' || m === null || Array.isArray(m)) throw err('packet', 'must be a JSON object');
110|  const def = MESSAGES[m.type];
111|  if (!def) throw err('packet', `unknown message type ${JSON.stringify(m.type)}`);
112|  const known = Object.keys(def.fields);
113|  for (const k of Object.keys(m)) if (k !== 'type' && !known.includes(k)) throw err(m.type, `unknown field ${k}`);
114|  const data = {};
115|  for (const [f, check] of Object.entries(def.fields)) data[f] = check(m[f], `${m.type}.${f}`);
116|  return { type: m.type, data };
117|}
118|
119|// Markdown table of the whole protocol, generated from the registry. NOTES.md
120|// embeds it between markers; a test keeps the two from drifting apart.
121|export function protocolTable() {
122|  const rows = Object.entries(MESSAGES).map(([name, d]) =>
123|    `| ${name} | ${d.dir === 'cs' ? 'client → server' : 'server → client'} | ${Object.keys(d.fields).join(' ') || '—'} | ${d.rate} |`);
124|  return ['| type | from | fields | rate |', '|---|---|---|---|', ...rows].join('\n');
