{"content": "1|/**
2| * Pure track layout for the multiplayer race: a 200 m straight run eastwards
3| * along *Unter den Linden*, starting just past the Brandenburger-Tor-style
4| * gate (the solo mode's own spawn road). Derived ONLY from the shared city
5| * data, so every client computing it from the same seed gets the same track.
6| *
7| * Coordinates: the city generator's plane — north = −z, so east = +x and
8| * "facing east" = heading Math.PI / 2 (like cityGen's spawn).
9| *
10| * Pure data in, pure data out, runs in Node for the tests. Grid slots are
11| * validated "place-only" against the city colliders: every seat must clear
12| * buildings, medians, gate pillars and the world border before the race uses
13| * it. Counts toward the size budget — kept tight.
14| */
15|import { TAXI } from '../vehicle/carPhysics.js';
16|import { pushOut } from '../vehicle/collision.js';
17|
18|export const TRACK_LENGTH = 200;
19|const SLOT_GAP = 3.4; // grid spacing in the lane, north→south
20|const GRID_MARGIN = 1.5; // corridor clear of the colliders on both sides
21|
22|/**
23| * buildTrack(city, playerCount) →
24| *   { street, start, grid, finish, ampel, corridor, laneZ }
25| *
26| * - start   {x, z, heading}: the line the grid stands on
27| * - grid    [{x, z, heading}]: exactly playerCount seats, pole position first
28| * - finish  {x, z0, z1}: the chequered line segment across the racing lane
29| * - ampel   {x, z, heading}: the start light pole, on the central line ahead
30| * - corridor {x0, z0, x1, z1}: rect that must stay free of colliders, used
31| *   by the invariant tests ("track is fully on road, nothing in the way")
32| */
33|export function buildTrack(city, playerCount) {
34|  if (!Number.isInteger(playerCount) || playerCount < 2 || playerCount > 4)
35|    throw new RangeError('track: needs 2–4 players');
36|  const gate = city.landmarks.find((l) => l.kind === 'gate');
37|  const boulevard = city.streetsEW.find((s) => s.kind === 'boulevard');
38|  if (!gate || !boulevard) throw new RangeError('track: city has no boulevard or gate');
39|  const cfg = city.config;
40|
41|  // Start past the first north-south crossing east of the gate, so the grid
42|  // stands on an ordinary stretch of the boulevard, not across a junction.
43|  // (The solo mode's spawn is gate.x + 30 — at least that far east.)
44|  const crossing = city.streetsNS.find((s) => s.center + s.width / 2 > gate.x + 10);
45|  const start = {
46|    x: Math.max(gate.x + 30, (crossing ? crossing.center + crossing.width / 2 : gate.x) + 8),
47|    z: boulevard.center + cfg.medianWidth / 2 + 3.5,
48|    heading: Math.PI / 2,
49|  };
50|  const finish = {
51|    x: start.x + TRACK_LENGTH,
52|    z0: boulevard.center + cfg.medianWidth / 2 + GRID_MARGIN,
53|    z1: boulevard.center + cfg.boulevardWidth / 2 - GRID_MARGIN,
54|  };
55|  if (finish.x + GRID_MARGIN > city.bounds.x1 - 10)
56|    throw new RangeError('track: 200 m do not fit east of the gate');
57|
58|  // Seats side by side across the racing lane, starting just inside the clear band.
59|  const grid = Array.from({ length: playerCount }, (_, i) => ({
60|    x: start.x,
61|    z: start.z - 1.5 + i * SLOT_GAP,
62|    heading: Math.PI / 2,
63|  }));
64|  for (const slot of grid) {
65|    for (const off of [TAXI.collisionOffset, -TAXI.collisionOffset]) {
66|      if (pushOut(slot.x + off, slot.z, TAXI.collisionRadius, city.colliders))
67|        throw new RangeError('track: grid slot collides with the city');
68|    }
69|  }
70|  for (let a = 0; a < grid.length; a++)
71|    for (let b = a + 1; b < grid.length; b++)
72|      if (Math.hypot(grid[a].x - grid[b].x, grid[a].z - grid[b].z) < SLOT_GAP - 0.2)
73|        throw new RangeError('track: grid slots overlap');
74|
75|  const corridor = {
76|    x0: start.x - GRID_MARGIN * 1.5,
77|    z0: boulevard.center + cfg.medianWidth / 2 + 0.5,
78|    x1: finish.x + GRID_MARGIN,
79|    z1: boulevard.center + cfg.boulevardWidth / 2 - 0.5,
80|  };
81|  for (const c of city.colliders) {
82|    const box = c.type === 'box' ? c : null;
83|    if (box && box.x0 < corridor.x1 && box.x1 > corridor.x0 && box.z0 < corridor.z1 && box.z1 > corridor.z0)
84|      throw new RangeError('track: something is standing in the corridor');
85|  }
86|
87|  return {
88|    street: 'Unter den Linden',
89|    start,
90|    grid,
91|    finish,
92|    ampel: { x: start.x + 12, z: boulevard.center, heading: -Math.PI / 2 },
93|    corridor,
94|    laneZ: start.z,
95|  };
96|}", "total_lines": 96, "file_size": 4210, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// The rules of the race as one PURE module: no sockets, no real timers, no
2|// Math.random. Everything that touches the outside world is injected —
3|//
4|//   now()      → server time in ms (the master clock every decision is based on)
5|//   send(conn, type, data)      → deliver an outgoing message
6|//   close(conn, code, reason)   → reject a connection
7|//   schedule(delayMs, fn)       → a cancellable-by-us timer (setTimeout / FakeNet.schedule)
8|//
9|// That keeps the whole state machine (lobby → countdown → racing → finished →
10|// ceremony) runnable in node:test against FakeNet pairs, and lets main.mjs
11|// wire the real WebSocket connections into the same handlers.
12|//
13|// Official order: the server settles finish times — clients only REPORT, so a
14|// lying or late client can't change the podium. Ties go to the earliest report
15|// (arrival order), which keeps the result deterministic.
16|import { decode, encode, MAX_PLAYERS } from './protocol.js';
17|
18|// Close codes for turned-away connections (NOTES.md documents these).
19|export const CLOSE_FULL = 4000; // 4 already in the lobby
20|export const CLOSE_STARTED = 4001; // race already running
21|
22|export function createRaceState({
23|  seed,
24|  now = Date.now,
25|  send,
26|  close,
27|  schedule,
28|  countdownMs = 3000,
29|  resultsMs = 2000, // pause between the results table and the podium
30|  ceremonyAfterWinnerMs = 30000, // brief rule: ceremony at latest 30 s after the winner
31|}) {
32|  if (!Number.isInteger(seed) || seed < 0) throw new RangeError('raceState: seed must be a non-negative integer');
33|
34|  const lobby = new Map(); // conn → nothing yet: connected, has not sent join
35|  const players = new Map(); // conn → { id, name, finish: {t, seq} | null, dnf }
36|  let stage = 'lobby';
37|  let nextId = 1;
38|  let reportSeq = 0; // arrival order of finish reports, breaks time ties deterministically
39|  let goAt = null; // shared start moment, sent in countdown and go
40|  let winnerAt = null; // server time when the first finish was reported
41|  let settled = false; // results are out; final stage change pending
42|
43|  const roster = () => Array.from(players.values(), (p) => ({ id: p.id, name: p.name }));
44|  const broadcast = (type, data) => {
45|    for (const [conn, p] of players) if (!p.gone) send(conn, type, data);
46|  };
47|
48|  const toResults = () => {
49|    const byArrival = Array.from(players.values());
50|    const finished = byArrival.filter((p) => p.finish).sort((a, b) => a.finish.t - b.finish.t || a.finish.seq - b.finish.seq);
51|    // Everyone the race settled without a finish time is a DNF (disconnected
52|    // mid-race, or still driving when the 30 s window forced the result).
53|    const dnf = byArrival.filter((p) => !p.finish).sort((a, b) => a.id - b.id);
54|    return [...finished, ...dnf].map((p) => ({
55|      id: p.id, name: p.name, t: p.finish ? p.finish.t : null, dnf: !p.finish,
56|    }));
57|  };
58|
59|  // Ceremony fires when everyone is home (finish or DNF — a disconnect never
60|  // blocks it, brief acceptance criterion) or, at the latest, 30 s after the
61|  // winner crossed. Exactly once.
62|  const settle = () => {
63|    if (settled || winnerAt === null) return;
64|    const allDone = Array.from(players.values()).every((p) => p.finish || p.dnf);
65|    if (!allDone && now() - winnerAt < ceremonyAfterWinnerMs) return;
66|    settled = true;
67|    stage = 'finished';
68|    const results = toResults();
69|    broadcast('stage', { stage: 'finished' });
70|    broadcast('results', { players: results });
71|    schedule(resultsMs, () => {
72|      stage = 'ceremony';
73|      broadcast('stage', { stage: 'ceremony' });
74|    });
75|  };
76|
77|  const startCountdown = () => {
78|    stage = 'countdown';
79|    goAt = now() + countdownMs;
80|    broadcast('stage', { stage: 'countdown' });
81|    broadcast('countdown', { goAt });
82|    schedule(countdownMs, () => {
83|      stage = 'racing';
84|      broadcast('stage', { stage: 'racing' });
85|      broadcast('go', { goAt });
86|    });
87|  };
88|
89|  // --- Handlers the transport layer calls ---
90|
91|  // A new connection. In-lobby and under the cap → wait for join; anything
92|  // else → turned away with a documented close code before any game message.
93|  const connect = (conn) => {
94|    if (stage !== 'lobby') return close(conn, CLOSE_STARTED, 'race already started');
95|    if (players.size + lobby.size >= MAX_PLAYERS) return close(conn, CLOSE_FULL, 'lobby full');
96|    lobby.set(conn);
97|  };
98|
99|  // One text message from a connection, already framed. Malformed or
100|  // out-of-context messages are dropped silently — no state, no crash.
101|  const onMessage = (conn, text) => {
102|    let m = null;
103|    try { m = decode(text); } catch { return; } // unknown/malformed: drop
104|    const player = players.get(conn);
105|    switch (m.type) {
106|      case 'join': {
107|        if (stage !== 'lobby' || !lobby.has(conn) || player) return;
108|        lobby.delete(conn);
109|        players.set(conn, { id: nextId++, name: m.data.name, finish: null, dnf: false });
110|        for (const [c] of players) send(c, 'roster', { players: roster(), seed });
111|        break;
112|      }
113|      case 'name': {
114|        if (stage !== 'lobby' || !player) return;
115|        player.name = m.data.name;
116|        broadcast('roster', { players: roster(), seed });
117|        break;
118|      }
119|      case 'start': {
120|        if (stage !== 'lobby' || !player) return; // start gate: ≥ 2 players
121|        if (players.size >= 2) startCountdown();
122|        break;
123|      }
124|      case 'pos': {
125|        if (!['countdown', 'racing', 'finished'].includes(stage) || !player || player.gone) return;
126|        const { x, z, h, s } = m.data;
127|        for (const [other, peer] of players) if (other !== conn && !peer.gone) send(other, 'posRelay', { id: player.id, x, z, h, s });
